from modele import C,E

C('Formes et angles','Géométrie','Dès P1, puis approfondir',
 'Je décris les côtés, les sommets et les angles.','Formes découpées, règle, gabarit d’angle droit et équerre.',
 'Plie une feuille deux fois pour obtenir un coin droit. Compare ce gabarit aux coins de plusieurs formes tournées dans des sens différents.',
 ['Un angle droit correspond au coin de l’équerre. Il se code avec un petit carré.','Un angle aigu est plus petit qu’un angle droit ; un angle obtus est plus grand.','Un rectangle a quatre angles droits. Un carré a aussi quatre côtés de même longueur.'],
 'Un triangle rectangle a trois côtés et un angle droit. L’équerre permet de vérifier cet angle.',('angles',[90,45,120]),
 'Un carré tourné garde-t-il ses quatre angles droits ?', 'Oui. Tourner la feuille ne change pas les propriétés de la figure.',[
 E('Nomme les angles A, B et C : droit, aigu ou obtus.','A : droit ; B : aigu ; C : obtus.',('angles',[90,45,120])),
 E('Nomme les formes et explique comment reconnaître le carré tourné.','A : carré ; B : rectangle ; C : triangle rectangle. Le carré garde quatre côtés égaux et quatre angles droits.',('geoforms',None)),
 E('Combien de côtés, de sommets et d’angles droits a un rectangle ?','4 côtés, 4 sommets et 4 angles droits.'),
 E('Sur ta feuille, trace un angle droit avec l’équerre et code-le.','Les deux traits suivent les bords perpendiculaires de l’équerre ; un petit carré code l’angle.'),
 E('Un quadrilatère a quatre côtés égaux, mais ses angles ne sont pas droits. Est-ce un carré ?','Non. Quatre côtés égaux ne suffisent pas ; il faut aussi quatre angles droits.'),
 E('Dessine un triangle rectangle et marque son angle droit.','La figure a trois côtés et un angle qui coïncide avec le gabarit de l’équerre.'),
 E('Une forme a cinq côtés. Combien a-t-elle de sommets ?','5 sommets pour ce polygone simple.'),
 E('Trouve dans la classe deux angles droits et un angle qui ne l’est pas. Vérifie avec un gabarit.','Réponses selon les objets. Contrôler l’ajustement du gabarit.'),
 E('Lina dit : « Ce rectangle est penché, donc ce n’est plus un rectangle. » Explique.','L’orientation ne change pas les propriétés : les quatre angles restent droits et les côtés opposés gardent la même longueur.')],
 'Faire tourner les formes et contrôler avec les instruments, pas seulement à l’œil.', 'Les mots aigu et obtus sont utilisés sans mesure en degrés ni rapporteur.')

C('Alignements, milieux et cercles','Géométrie','P2 puis P3',
 'J’utilise la règle, le pliage et le compas.','Règle, papier et compas.',
 'Trace un segment sur une bande. Plie pour superposer ses extrémités : le pli indique le milieu. Place ensuite la pointe du compas sur un point et fais un tour sans changer l’écartement.',
 ['La règle permet de vérifier si des points sont alignés.','Le milieu partage un segment en deux segments de même longueur.','Un cercle a un centre ; tous ses points sont à la même distance de ce centre.'],
 'Pour tracer le cercle de centre O passant par A, je place la pointe sur O et j’ouvre le compas jusqu’à A.',('circle',None),
 'Un segment mesure 8 cm. Où se trouve son milieu ?', 'À 4 cm de chaque extrémité.',[
 E('Vérifie avec la règle si A, B et C sont alignés.','Oui : les trois points sont sur le même trait droit.',('points',[(0,0,'A'),(3,1,'B'),(6,2,'C')])),
 E('Trace un segment de 6 cm sur une bande, puis trouve son milieu par pliage.','Le pli coupe le segment à 3 cm de chaque extrémité.'),
 E('Sur une feuille séparée, marque O et A séparés de 3 cm. Trace le cercle de centre O passant par A.','La pointe reste sur O et l’écartement reste OA, soit 3 cm.'),
 E('Quel point est le centre du cercle représenté ? Quel point est sur le cercle ?','O est le centre ; A est sur le cercle.',('circle',None)),
 E('Trace trois points alignés et un quatrième qui ne soit pas sur le même trait.','Trois points sur une même droite ; le quatrième en dehors.'),
 E('Sur le dessin d’un cercle, colorie toute la surface intérieure. Comment appelle-t-on la surface obtenue avec son bord ?','Un disque : il comprend l’intérieur et le bord.'),
 E('Un segment mesure 10 cm. Son milieu est à quelle distance de chacune des extrémités ?','5 cm de chaque extrémité.'),
 E('Trace deux cercles de même centre et d’écartements différents sur ta feuille.','Même point fixe pour la pointe ; deux ouvertures différentes du compas.'),
 E('Noé déplace la pointe du compas pendant son tour. Obtiendra-t-il le cercle de centre O demandé ?','Non. La pointe doit rester fixe sur O et l’ouverture doit rester constante.')],
 'Apprendre séparément à tenir la pointe, à garder l’ouverture et à faire tourner le compas.', 'Ne pas exiger de formules du cercle ; faire découvrir le milieu par pliage et le vérifier.')

C('Construire avec les instruments','Géométrie','P2 à P5',
 'Je reproduis des figures sur plusieurs supports.','Règle, équerre, papier quadrillé, pointé et uni.',
 'Sur papier uni, trace un côté de rectangle, puis un angle droit à chaque extrémité. Compare avec une construction sur quadrillage.',
 ['Je repère les sommets avant de tracer les côtés.','Sur papier uni, la règle contrôle les longueurs et l’équerre les angles droits.','Un côté peut être oblique sur le quadrillage sans changer la nature de la figure.'],
 'Pour un rectangle de 6 cm sur 3 cm, je trace quatre angles droits ; les côtés opposés mesurent respectivement 6 cm et 3 cm.',('obliquegrid',False),
 'Sur ta feuille, construis un carré de 4 cm de côté.', 'Quatre côtés de 4 cm et quatre angles droits, vérifiés avec la règle et l’équerre.',[
 E('Reproduis le carré oblique sur le quadrillage vide. Vérifie ses angles droits.','Même suite de déplacements entre sommets ; les côtés sont égaux et les côtés consécutifs sont perpendiculaires.',('obliquegrid',True)),
 E('Sur papier uni, construis un rectangle de 5 cm sur 3 cm.','Deux côtés de 5 cm, deux côtés de 3 cm et quatre angles droits.'),
 E('Complète ce rectangle dont deux côtés sont tracés.','Ajouter les deux côtés opposés, en gardant les longueurs et les angles droits.',('partial',('rectangle',4,2))),
 E('Sur papier uni, construis un triangle rectangle dont les deux côtés de l’angle droit mesurent 4 cm et 3 cm.','Deux segments de 4 et 3 cm perpendiculaires ; relier leurs extrémités libres.'),
 E('Construis un carré de 3 cm de côté. Trace une diagonale. Quelles formes obtiens-tu ?','Deux triangles rectangles identiques.'),
 E('Reproduis le triangle sur le quadrillage vide.','Conserver les sommets du modèle et les déplacements entre eux.',('copygrid',('triangle',4,3))),
 E('Sur ta feuille, trace un rectangle de 6 cm sur 2 cm, puis un cercle centré sur un sommet et passant par le sommet voisin à 2 cm.','Le rectangle respecte les longueurs ; le cercle est centré sur le sommet choisi et son ouverture est de 2 cm.'),
 E('Lina construit une figure de quatre côtés égaux sans vérifier les angles. Peut-elle affirmer que c’est un carré ?','Non. Elle doit aussi vérifier les quatre angles droits.'),
 E('Écris une consigne qui permet à un camarade de construire le même rectangle que toi.','Préciser les deux longueurs et demander les quatre angles droits. Comparer les constructions.')],
 'Faire marquer les sommets et les angles droits avant de compléter la figure.', 'Varier papier quadrillé, pointé et uni ; un carré peut avoir ses côtés obliques sur le quadrillage.')

C('Solides, faces, arêtes et sommets','Géométrie','P2 puis P3',
 'Je reconnais les solides et je décris ce qu’on peut toucher.','Cube, pavé, pyramide à base carrée, boule, cylindre et cône.',
 'Manipule un cube et une pyramide à base carrée. Marque les faces déjà comptées, suis les arêtes du doigt et repère les sommets.',
 ['Une face est une surface plane du solide ; une arête est le bord commun à deux faces planes.','Un cube a 6 faces carrées, 12 arêtes et 8 sommets.','Une pyramide à base carrée a 1 face carrée et 4 faces triangulaires.'],
 'La pyramide à base carrée a 5 faces, 8 arêtes et 5 sommets. Certaines parties sont cachées sur le dessin.',('solids6',None),
 'Décris les faces d’un pavé droit.', 'Il a 6 faces rectangulaires ; certaines peuvent être carrées.',[
 E('Nomme les solides A à F.','A : cube ; B : pavé droit ; C : boule ; D : cylindre ; E : cône ; F : pyramide à base carrée.',('solids6',None)),
 E('Manipule un cube. Compte ses faces, ses arêtes et ses sommets.','6 faces, 12 arêtes, 8 sommets.'),
 E('Manipule un pavé droit. Compte ses faces, ses arêtes et ses sommets.','6 faces, 12 arêtes, 8 sommets.'),
 E('Une pyramide à base carrée a combien de faces triangulaires ? Combien de faces en tout ?','4 faces triangulaires ; 5 faces en tout.'),
 E('Construis le squelette d’un cube avec des tiges de même longueur et de la pâte. Combien de tiges et de boules de pâte faut-il ?','12 tiges pour les arêtes et 8 boules de pâte pour les sommets.'),
 E('Avec les faces découpées en annexe et un modèle réel, construis une pyramide à base carrée.','Un carré pour la base et quatre triangles qui se rejoignent au sommet ; les bords se correspondent.'),
 E('Quel solide ressemble à une boîte de conserve ? À une balle ?','Cylindre ; boule.'),
 E('Une image montre seulement 3 faces d’un pavé. Combien de faces possède le pavé réel ?','6 faces : le dessin cache certaines faces.'),
 E('Construis un assemblage de deux cubes côte à côte, puis un troisième sur le cube de gauche. Fais-le reproduire par un camarade.','Trois cubes disposés comme le modèle ; vérifier la position du cube supérieur.',('assembly',None))],
 'Compter sur des objets réels en marquant les éléments déjà comptés.', 'Au CE1, décrire et assembler les solides ; dessiner soi-même une perspective n’est pas un objectif.')

C('Plans et déplacements','Espace','Toute l’année',
 'Je localise un lieu et je code un trajet.','Plan de l’école, figurine orientée et quadrillage.',
 'Dessine un plan simple de l’école avec la classe, la cour et la cantine. Fais parcourir un trajet réel, puis représente-le sur le plan.',
 ['Un plan représente les positions des lieux vus de dessus.','Je précise le départ et l’orientation du personnage.','Tourner sur place change la direction ; avancer déplace le personnage dans la direction où il regarde.'],
 'Le pion regarde vers le haut : avancer de 2 cases, tourner à droite, avancer de 1 case.',('route',None),
 'Le pion regarde vers la gauche et tourne à droite. Vers où regarde-t-il ?', 'Vers le haut du plan.',[
 E('Le pion regarde vers le haut. Trace : avance de 2 cases, tourne à droite, avance de 1 case.','Deux cases vers le haut, puis une vers la droite.',('routeblank',None)),
 E('Dessine un plan de l’école et place trois lieux connus.','Positions relatives cohérentes : classe, cour, cantine ou autres lieux familiers.'),
 E('Décris un objet près de la porte et un autre loin de la porte.','Réponses adaptées à la salle et au repère choisi.'),
 E('Le pion regarde vers la droite. Il tourne à droite puis avance d’une case. Où va-t-il sur le plan ?','Une case vers le bas.'),
 E('Le pion regarde vers le haut. Il avance de 2, tourne à droite, avance de 3, tourne à droite et avance de 2. Où arrive-t-il par rapport au départ ?','Trois cases à droite du départ, sur la même ligne ; il regarde vers le bas.'),
 E('Sur le plan de l’école, code un trajet d’au plus 10 instructions et 3 virages. Fais-le suivre.','Le trajet doit être réalisable, son départ et son orientation doivent être précisés.'),
 E('Depuis le départ et en regardant vers le haut : avance de 1, tourne à droite, avance de 2, tourne à droite, avance de 1, tourne à droite, avance de 2, tourne à droite. Où finis-tu ?','Au point de départ, en regardant vers le haut.'),
 E('Avec l’adulte, compare un plan de l’école et une photographie vue du dessus. Trouve deux lieux sur les deux supports.','Les mêmes lieux sont repérés malgré les différences de taille et de représentation.'),
 E('Noé confond « tourne à droite » et « déplace-toi d’une case à droite ». Explique avec ton corps.','Tourner se fait sur place. Avancer ensuite dépend de la nouvelle orientation.')],
 'Faire vivre le trajet avec le corps avant de coder et préciser le point de vue.', 'Au plus 15 instructions et 4 virages dans les parcours programmés du CE1 ; adapter les trajets à l’espace réel.')

C('Enquêter et construire un graphique','Données','P2 à P5',
 'Je recueille des réponses et je représente les effectifs.','Feuille d’enquête, cubes et crayons.',
 'Pose à 6 à 12 personnes une même question avec trois choix : lecture, dessin ou ballon. Chacun donne une seule réponse. Note une marque par vote.',
 ['Je prépare des choix clairs et je note chaque réponse une fois.','Un tableau rassemble les effectifs de chaque choix.','Sur le graphique, une case représente une personne ; je nomme les barres et l’échelle.'],
 'Si lecture reçoit 4 votes, dessin 3 et ballon 5, le total est 12 votes. Les hauteurs des barres sont 4, 3 et 5.',('databars',[['Lecture','Dessin','Ballon'],[4,3,5]]),
 'Avec 2, 4 et 3 votes, combien de personnes ont répondu ?', '2 + 4 + 3 = 9 personnes.',[
 E('Interroge 6 à 12 personnes sur leur préférence : lecture, dessin ou ballon. Note les réponses.','Une réponse par personne ; de 6 à 12 marques au total.'),
 E('Compte tes réponses et complète le tableau d’enquête.','Les trois effectifs correspondent aux marques recueillies ; leur somme égale le nombre de participants.',('survey3',None)),
 E('Construis ton graphique avec tes propres résultats. Colorie une case par personne.','Trois barres conformes aux effectifs, choix nommés, échelle de un en un.',('surveygraph',None)),
 E('Avec tes résultats, annonce le choix le plus fréquent ou les choix à égalité.','Réponse selon l’enquête ; comparer les effectifs.'),
 E('Vérifie que le nombre total de cases coloriées égale le nombre de personnes interrogées.','Les deux totaux doivent être identiques. En cas d’écart, recompter les marques et les barres.'),
 E('Une personne donne deux choix alors qu’un seul est autorisé. Que fais-tu ?','Lui demander de choisir une seule réponse et ne la compter qu’une fois.'),
 E('Prépare une nouvelle enquête sur un sujet de ton choix, avec deux à cinq réponses possibles.','Question claire, choix distincts, une réponse par personne ; moins de 100 personnes.'),
 E('Présente les résultats de ta nouvelle enquête par un tableau puis par des barres.','Même effectif dans le tableau et le graphique ; axe gradué de un en un, catégories et titre.'),
 E('Explique à un camarade ce que représente la hauteur d’une barre.','Le nombre de personnes qui ont choisi la réponse nommée sous la barre.')],
 'Construire d’abord des tours de cubes, puis passer aux barres dessinées.', 'Ne pas confondre hauteur de barre et nombre de choix ; effectuer un vrai recueil de données.')

C('Lire les tableaux et les graphiques','Données','P3 à P5',
 'Je cherche une information à l’intersection d’une ligne et d’une colonne.','Tableaux et graphiques simples.',
 'Fabrique un tableau avec les lignes « à pied, à vélo » et les colonnes « lundi, mardi ». Place des jetons dans une case et décris les deux informations qu’elle réunit.',
 ['Je lis le titre et les étiquettes avant de répondre.','Une case d’un tableau à double entrée réunit les informations de sa ligne et de sa colonne.','Sur un graphique, je lis l’échelle et le nom de la barre.'],
 'La case « à vélo, mardi » indique 7 élèves. Il faut suivre la ligne à vélo et la colonne mardi.',('doubledata',None),
 'Dans le tableau, combien viennent à pied le lundi ?', '8 élèves.',[
 E('Combien d’élèves viennent à vélo le mardi ?','7 élèves.',('doubledata',None)),
 E('Combien viennent à pied et à vélo le lundi, au total ?','8 + 5 = 13 élèves.',None,'8+5==13'),
 E('Quel jour compte le plus d’élèves à vélo ? Quel est l’écart ?','Mardi : 7 contre 5 lundi. L’écart est 2.',None,'7-5==2'),
 E('Lis le graphique : quel jeu a le plus de votes ? Combien de votes pour dessin ?','Ballon a le plus de votes : 6. Dessin reçoit 3 votes.',('databars',[['Lecture','Dessin','Ballon'],[4,3,6]])),
 E('Combien de personnes ont voté dans le graphique précédent ?','4 + 3 + 6 = 13 personnes.',None,'4+3+6==13'),
 E('Combien de votes de plus pour ballon que pour dessin ?','6 - 3 = 3 votes.',None,'6-3==3'),
 E('Le tableau donne 10 élèves à pied le mardi et 7 à vélo le mardi. Quel est le total mardi ?','10 + 7 = 17 élèves.',None,'10+7==17'),
 E('Un graphique est dessiné sans noms sous les barres. Pourquoi est-ce gênant ?','On ne sait pas à quel choix correspond chaque effectif.'),
 E('Invente une question dont la réponse se lit dans une seule case du tableau, puis une question qui demande un calcul.','Exemples : à vélo lundi ? 5. Total mardi ? 10 + 7 = 17. Vérifier toute autre question proposée.')],
 'Faire poser un doigt sur l’étiquette de ligne et un autre sur l’étiquette de colonne.', 'Lire les unités et l’échelle ; le plus grand nombre imprimé n’est pas toujours la réponse à la question.')
